import fitz

doc = fitz.open("latex_paper.pdf")
page = doc[2]  # Page 3

# Get detailed text with positions
blocks = page.get_text("dict")["blocks"]
for block in blocks:
    if "lines" in block:
        for line in block["lines"]:
            text = ""
            for span in line["spans"]:
                text += span["text"]
            if "exp" in text or "η" in text or "Ω" in text or "prod" in text or "H_" in text:
                print(f"Line: {text}")
EOF
